import os, glob, re, json

# Load all grids from this session
def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    try:
        t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    except:
        return {}
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        # Look ahead up to some rows to safely extract
        start = m.end()
        limit = 1000
        snippet = t[start:start+limit]
        rows = [r.split() for r in snippet.split('\n')[:h]]
        valid = all(len(r) == w and all(x.isdigit() for x in r) for r in rows[:h])
        if valid:
            G[k] = [[int(x) for x in r] for r in rows[:h]]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k in sorted(G):
    print(f"\n--- {k} ---")
    for row in G[k]:
        print(row)
